#include <bits/stdc++.h>
using namespace std;

/**
 * Alternative implementation with different variable naming and structure.
 */

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, l;
    cin >> n >> k >> l;

    const int MOD = 998244353;

    // Function to compute modular inverse array
    auto invs = [&](int size, long long p) {
        vector<long long> res(size);
        res[1] = 1;
        for (int i = 2; i < size; i++) {
            res[i] = (p - (p / i) * res[p % i] % p) % p;
        }
        return res;
    };

    vector<long long> invs_arr = invs(2 * n + 4, MOD);

    vector<vector<long long>> dp(2 * n + 1, vector<long long>(n + 1, 0));
    dp[0][1] = 1;

    for (int i = 1; i < 2 * n; i++) {
        int maxPrev = min(2 * n - i, i);
        int maxCurr = min(2 * n - i - 1, i + 1);
        for (int j = 0; j <= maxPrev; j++) {
            if (dp[i - 1][j] != 0) {
                if (j > 0) {
                    dp[i][j - 1] = (dp[i][j - 1] + dp[i - 1][j] * j % MOD * invs_arr[2 * n - i]) % MOD;
                }
                if (j < maxCurr) {
                    dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j] * (2 * n - i - j) % MOD * invs_arr[2 * n - i]) % MOD;
                }
            }
        }
    }

    long long answer = 0;
    for (int i = 0; i < 2 * n; i++) {
        for (int j = k; j <= n; j++) {
            answer = (answer + dp[i][j]) % MOD;
        }
    }
    answer = answer * l % MOD * invs_arr[2 * n + 1] % MOD;
    cout << answer << "\n";

    return 0;
}

